// ofxManifoldPlayer -- OSC out conformance runner (round 3B-1).
//
// Reads tests/vectors/osc.vec, generated by tests/ref/reference_osc.py, whose
// encodings are checked there against python-osc. Every ENCODE is also
// decoded back here, so the encoder and decoder agree with each other as well
// as with the reference.

#include "../ofxManifoldPlayer/src/ofxManifoldOsc.h"

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

using namespace ofxManifold::player;

namespace {

std::string trim(const std::string& s) {
    const auto a = s.find_first_not_of(' ');
    if (a == std::string::npos) return "";
    const auto b = s.find_last_not_of(' ');
    return s.substr(a, b - a + 1);
}

std::vector<std::string> fields(const std::string& line) {
    std::vector<std::string> out;
    std::size_t at = 0;
    while (true) {
        const auto k = line.find(" | ", at);
        if (k == std::string::npos) { out.push_back(trim(line.substr(at))); break; }
        out.push_back(trim(line.substr(at, k - at)));
        at = k + 3;
    }
    return out;
}

// Arguments as text: space-separated, strings in double quotes.
std::vector<std::string> tokens(const std::string& s) {
    std::vector<std::string> out;
    std::size_t i = 0;
    while (i < s.size()) {
        if (s[i] == ' ') { ++i; continue; }
        if (s[i] == '"') {
            const auto e = s.find('"', i + 1);
            out.push_back(s.substr(i, e - i + 1));
            i = e + 1;
        } else {
            auto e = s.find(' ', i);
            if (e == std::string::npos) e = s.size();
            out.push_back(s.substr(i, e - i));
            i = e;
        }
    }
    return out;
}

std::string fmtf(float f) {
    char b[64];
    std::snprintf(b, sizeof b, "%.9g", double(f));
    return b;
}

std::string argText(const OscMessage& m) {
    std::string out;
    for (const OscArg& a : m.args) {
        if (!out.empty()) out += " ";
        if (a.type == 'f') out += fmtf(a.f);
        else if (a.type == 'i') out += std::to_string(a.i);
        else out += "\"" + a.s + "\"";
    }
    return out;
}

std::string msgLine(const OscMessage& m) {
    std::string t = "MSG " + m.address + " " + m.tags();
    const std::string a = argText(m);
    if (!a.empty()) t += " " + a;
    return t;
}

OscMessage build(const std::string& address, const std::string& tags,
                 const std::string& args) {
    OscMessage m;
    m.address = address;
    const auto toks = tokens(args);
    for (std::size_t k = 1; k < tags.size(); ++k) {
        const std::string& v = toks.at(k - 1);
        if (tags[k] == 'i') m.args.push_back(OscArg::integer(std::stoi(v)));
        else if (tags[k] == 'f') m.args.push_back(OscArg::number(std::stof(v)));
        else m.args.push_back(OscArg::text(v.substr(1, v.size() - 2)));
    }
    return m;
}

std::string hex(const std::vector<std::uint8_t>& b) {
    static const char* d = "0123456789abcdef";
    std::string s;
    for (std::uint8_t c : b) { s += d[c >> 4]; s += d[c & 15]; }
    return s;
}

std::vector<std::uint8_t> unhex(const std::string& s) {
    std::vector<std::uint8_t> b;
    if (s == "-") return b;
    for (std::size_t i = 0; i + 1 < s.size(); i += 2) {
        b.push_back(std::uint8_t(std::stoi(s.substr(i, 2), nullptr, 16)));
    }
    return b;
}

}  // namespace

int main(int argc, char** argv) {
    const std::string path = argc > 1 ? argv[1] : "tests/vectors/osc.vec";
    std::ifstream in(path);
    if (!in) { std::cerr << "cannot open " << path << "\n"; return 2; }
    std::cout << "ofxManifoldPlayer OSC out\nvectors: " << path << "\n\n";

    int pass = 0, fail = 0;
    auto report = [&](bool ok, const std::string& kind, const std::string& name,
                      const std::string& why) {
        if (ok) { ++pass; std::cout << "  pass  " << kind << "  " << name << "\n"; }
        else { ++fail; std::cout << "  FAIL  " << kind << "  " << name << ": " << why << "\n"; }
    };

    std::vector<std::string> lines;
    for (std::string l; std::getline(in, l);) lines.push_back(l);

    for (std::size_t i = 0; i < lines.size(); ++i) {
        const std::string& line = lines[i];
        if (line.empty() || line[0] == '#') continue;
        const std::string kind = line.substr(0, line.find(' '));
        if (kind == "ENCODE") {
            const auto f = fields(line.substr(7));
            const std::string name = f[0];
            const OscMessage m = build(f[1], f[2], f[3]);
            const auto bytes = encode(m);
            std::string why;
            if (hex(bytes) != f[4]) why = "bytes " + hex(bytes) + " want " + f[4];
            OscMessage back;
            if (why.empty() && (!decode(bytes.data(), bytes.size(), back)
                                || back.address != m.address || back.tags() != m.tags()
                                || argText(back) != argText(m))) {
                why = "does not decode back to itself";
            }
            report(why.empty(), "ANALYTIC", "encode " + name, why);
        } else if (kind == "DECODE") {
            const auto f = fields(line.substr(7));
            const auto bytes = unhex(f[1]);
            OscMessage m;
            std::string why;
            if (!decode(bytes.data(), bytes.size(), m)) why = "refused";
            else if (m.address != f[2] || m.tags() != f[3] || argText(m) != f[4]) {
                why = "got " + m.address + " " + m.tags() + " " + argText(m);
            }
            report(why.empty(), "CROSS   ", "decode " + f[0], why);
        } else if (kind == "REFUSE") {
            const auto f = fields(line.substr(7));
            const auto bytes = unhex(f[1]);
            OscMessage m;
            const bool got = decode(bytes.data(), bytes.size(), m);
            report(!got, "ANALYTIC", "refuse " + f[0], "decoded what should be refused");
        } else if (kind == "SEND") {
            std::istringstream ss(line.substr(5));
            std::string name, tok;
            ss >> name;
            OscOut out;
            while (ss >> tok) {
                const auto eq = tok.find('=');
                const std::string k = tok.substr(0, eq), v = tok.substr(eq + 1);
                if (k == "prefix") out.setPrefix(v);
                else if (k == "packed") out.setPacked(v == "1");
                else if (k == "per_output") out.setPerOutput(v == "1");
                else if (k == "rate") out.setRate(std::stod(v));
            }
            std::string why;
            std::size_t j = i + 1;
            for (; j < lines.size() && lines[j] != "END"; ++j) {
                const std::string& s = lines[j];
                if (!why.empty()) continue;
                if (s.rfind("FRAME ", 0) == 0) {
                    const auto f = fields(s.substr(6));
                    const double now = std::stod(f[0]);
                    OscFrame fr;
                    if (f[1] != "-") {
                        std::stringstream os(f[1]);
                        for (std::string item; std::getline(os, item, ',');) {
                            const auto b = item.rfind(':');
                            const auto a = item.rfind(':', b - 1);
                            fr.outputs.push_back({item.substr(0, a),
                                                  std::stoi(item.substr(a + 1, b - a - 1)),
                                                  std::stof(item.substr(b + 1))});
                        }
                    }
                    if (f[2] != "-") {
                        std::stringstream vs(f[2]);
                        for (std::string item; std::getline(vs, item, ',');) {
                            const auto b = item.rfind(':');
                            fr.values.push_back({item.substr(0, b),
                                                 std::stof(item.substr(b + 1))});
                        }
                    }
                    if (f[3] != "-") {
                        std::istringstream ps(f[3]);
                        ps >> fr.position.x >> fr.position.y >> fr.position.z;
                        fr.hasPosition = true;
                    }
                    const std::size_t want = std::stoul(f[4]);
                    const auto msgs = out.frame(now, fr);
                    if (msgs.size() != want) {
                        why = "at " + f[0] + ": " + std::to_string(msgs.size())
                            + " messages, want " + std::to_string(want);
                        if (!msgs.empty()) why += " -- first " + msgLine(msgs[0]);
                        continue;
                    }
                    for (std::size_t k = 0; k < want; ++k) {
                        const std::string got = msgLine(msgs[k]);
                        if (got != lines[j + 1 + k]) {
                            why = "at " + f[0] + ": " + got + " -- want " + lines[j + 1 + k];
                            break;
                        }
                    }
                    j += want;
                } else if (s.rfind("RECV ", 0) == 0) {
                    std::istringstream rs(s.substr(5));
                    double now; std::string address, tags;
                    rs >> now >> address >> tags;
                    std::string rest;
                    std::getline(rs, rest);
                    out.receive(now, build(address, tags, trim(rest)));
                } else if (s.rfind("CONN ", 0) == 0) {
                    std::istringstream cs(s.substr(5));
                    double now; int flag; std::string peer;
                    cs >> now >> flag;
                    std::getline(cs, peer);
                    peer = trim(peer);
                    const bool c = out.connected(now);
                    const std::string gotPeer = "\"" + (c ? out.peer() : std::string()) + "\"";
                    if (int(c) != flag || gotPeer != peer) {
                        why = "connected at " + std::to_string(now) + ": "
                            + std::to_string(int(c)) + " " + gotPeer;
                    }
                }
            }
            report(why.empty(), "SPEC    ", "send " + name, why);
            i = j;
        }
    }
    std::cout << "\n" << pass << "/" << (pass + fail) << "  "
              << (fail ? "RED" : "GREEN") << "\n";
    return fail ? 1 : 0;
}
